import { Box, IconButton, Menu, MenuItem, Tooltip, Typography } from '@mui/material'
import ArrowDown from 'mdi-material-ui/ArrowDown'
import ArrowUp from 'mdi-material-ui/ArrowUp'
import SourceBranch from 'mdi-material-ui/SourceBranch'
import { useState } from 'react'
import type { MouseEvent } from 'react'
import type { WorktreeRecord } from '../data/data_types'
import { dialogService } from '../services/dialog_service'
import { configService } from '../services/config/config_service'
import { worktreeService } from '../services/project/worktree_service'
import { useConfigValueOrFallback } from './hooks/use_config_value'
import { useWorktreeSelectorState } from './hooks/use_worktree_selector_state'
import { WorktreeCommitDialog } from './worktree_commit_dialog'
import { WorktreeIntegrationDialog } from './worktree_integration_dialog'
import { WorktreeUnassignDialog } from './worktree_unassign_dialog'

export interface WorktreeAssignment {
    worktree?: number | null
    worktreeError?: string | null
    worktreeValue?: string | null
}

export type WorktreeAssignmentTarget = { kind: 'card', path: string } | { kind: 'project' }
type CommitAction = 'commit' | 'integrate' | 'update'

interface WorktreeSelectorProps {
    assignment: WorktreeAssignment
    assignmentTarget: WorktreeAssignmentTarget
    disabled?: boolean
    labelPrefix?: string
    primaryPath: string | null
}

function assignmentState(assignment: WorktreeAssignment, worktrees: WorktreeRecord[]) {
    if (assignment.worktreeError) {
        return { error: assignment.worktreeError, folder: 'invalid assignment', value: assignment.worktreeValue ?? '?' }
    }
    const worktree = assignment.worktree ?? null
    if (worktree === null) return { error: null, folder: null, value: 'P' }

    const record = worktrees[worktree - 1]
    if (!record) return { error: `Configured worktree ${worktree} does not exist`, folder: 'missing folder', value: String(worktree) }
    if (!record.valid) return { error: `${record.path}: ${record.error}`, folder: record.path, value: String(worktree) }

    return { error: null, folder: record.path, value: String(worktree) }
}

/** Shared worktree assignment button and menu used by cards and action popups. */
export function WorktreeSelector(props: WorktreeSelectorProps) {
    const { assignment, assignmentTarget, disabled = false, labelPrefix, primaryPath } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const [commitMessage, setCommitMessage] = useState('')
    const [commitAction, setCommitAction] = useState<CommitAction>('commit')
    const [commitDialogOpen, setCommitDialogOpen] = useState(false)
    const [deleteBranchAfterCommit, setDeleteBranchAfterCommit] = useState(false)
    const [integrationDialogOpen, setIntegrationDialogOpen] = useState(false)
    const [unassignDialogOpen, setUnassignDialogOpen] = useState(false)
    const deleteBranchPreference = useConfigValueOrFallback('react.deleteBranchAfterIntegration', false)
    const cardPath = assignmentTarget.kind === 'card' ? assignmentTarget.path : null
    const assignedWorktree = assignment.worktree ?? null
    const {
        preparing,
        projectDirty: hasPendingProjectChanges,
        record: assignedRecord,
        records: worktrees,
    } = useWorktreeSelectorState({ assignedWorktree, cardPath })
    const selectorDisabled = disabled || preparing
    const state = assignmentState(assignment, worktrees)
    const hasActiveCardWorktree = assignmentTarget.kind === 'card' && assignedWorktree !== null
        && !state.error && !!assignedRecord?.valid
    const hasActiveProjectWorktree = assignmentTarget.kind === 'project' && assignedWorktree !== null
        && !state.error && !!assignedRecord?.valid
    const canCommit = !!assignedRecord?.status.dirty
    const hasOutgoingChanges = !!assignedRecord
        && (assignedRecord.status.dirty || assignedRecord.status.baseAhead > 0)
    const hasIncomingChanges = !!assignedRecord && (hasPendingProjectChanges || assignedRecord.status.baseBehind > 0)
    const hasWorktreeChanges = hasOutgoingChanges || hasIncomingChanges
    const projectBranch = worktreeService.getProjectBranch()
    const folder = state.folder ?? primaryPath ?? 'Primary'
    const assignmentDescription = state.error
        ? `Worktree assignment error: ${state.error}`
        : state.value === 'P'
            ? `Primary worktree${primaryPath ? `: ${primaryPath}` : ''}`
            : `Worktree ${state.value}: ${folder}`
    const baseName = projectBranch ?? 'the project branch'
    const statusParts = assignedRecord
        ? [
            `dirty ${assignedRecord.status.dirty ? 'yes' : 'no'}`,
            `project changes pending ${hasPendingProjectChanges ? 'yes' : 'no'}`,
            `ahead of ${baseName} ${assignedRecord.status.baseAhead}`,
            `behind ${baseName} ${assignedRecord.status.baseBehind}`,
        ]
        : []
    const worktreeStatusDescription = statusParts.length > 0 ? statusParts.join('; ') : null
    const descriptions = [assignmentDescription, worktreeStatusDescription].filter((value) => value !== null)
    const tooltip = descriptions.join('. ')
    const statusLabel = worktreeStatusDescription ? `; ${worktreeStatusDescription}` : ''
    const label = labelPrefix
        ? `${labelPrefix}: ${folder}${statusLabel}`
        : `${assignmentDescription}${statusLabel}`

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        setAnchorElement(event.currentTarget)
    }
    const handleClose = () => setAnchorElement(null)
    const assignWorktree = async (worktree: number | null) => {
        try {
            if (assignmentTarget.kind === 'project') worktreeService.setProjectActionWorktree(worktree)
            else await worktreeService.setCardWorktree(assignmentTarget.path, worktree)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not update worktree assignment' })
        }
    }
    const handlePrimary = async () => {
        handleClose()
        if (hasActiveCardWorktree) {
            try {
                if (hasOutgoingChanges) {
                    if (!assignedRecord?.status.dirty) {
                        await worktreeService.integrateCardWorktree(assignmentTarget.path, false)
                        await worktreeService.setCardWorktree(assignmentTarget.path, null)
                        return
                    }
                    setCommitMessage(worktreeService.getCardCommitMessage(assignmentTarget.path))
                    setUnassignDialogOpen(true)
                    return
                }
                await worktreeService.setCardWorktree(assignmentTarget.path, null)
                return
            } catch (error) {
                if (worktreeService.getRecords()[assignedWorktree - 1]?.status.dirty) {
                    setCommitMessage(worktreeService.getCardCommitMessage(assignmentTarget.path))
                    setUnassignDialogOpen(true)
                    return
                }
                dialogService.error(error, { fallbackMessage: 'Could not update worktree assignment' })
                return
            }
        }
        await assignWorktree(null)
    }
    const handleWorktree = async (event: MouseEvent<HTMLElement>) => {
        try {
            const worktree = Number.parseInt(event.currentTarget.dataset.worktree ?? '', 10)
            if (!Number.isInteger(worktree)) throw new Error('Missing worktree menu index')

            handleClose()
            await assignWorktree(worktree)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not update worktree assignment' })
        }
    }
    const getCommitMessage = () => (assignmentTarget.kind === 'card'
        ? worktreeService.getCardCommitMessage(assignmentTarget.path)
        : worktreeService.getProjectCommitMessage())
    const handleCommitMenu = () => {
        handleClose()
        try {
            setCommitMessage(getCommitMessage())
            setCommitAction('commit')
            setCommitDialogOpen(true)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not prepare worktree commit' })
        }
    }
    const handleIntegrateMenu = async () => {
        handleClose()
        try {
            if (assignmentTarget.kind === 'card') {
                setIntegrationDialogOpen(true)
                return
            }
            if (assignedRecord?.status.dirty) {
                setCommitMessage(getCommitMessage())
                setCommitAction('integrate')
                setCommitDialogOpen(true)
                return
            }
            await worktreeService.integrateProjectWorktree()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not integrate worktree into project' })
        }
    }
    const handleUpdateMenu = async () => {
        handleClose()
        try {
            if (assignedRecord?.status.dirty) {
                setCommitMessage(getCommitMessage())
                setCommitAction('update')
                setCommitDialogOpen(true)
                return
            }
            if (assignmentTarget.kind === 'card') await worktreeService.updateCardWorktree(assignmentTarget.path)
            else await worktreeService.updateProjectWorktree()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Could not update worktree from ${baseName}` })
        }
    }
    const handleCommitDialogClose = () => setCommitDialogOpen(false)
    const handleCommit = async (message: string) => {
        try {
            if (assignmentTarget.kind === 'card') await worktreeService.commitCardWorktree(assignmentTarget.path, message)
            else await worktreeService.commitProjectWorktree(message)
            setCommitDialogOpen(false)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not commit worktree changes' })
            return
        }
        try {
            if (commitAction === 'integrate') {
                if (assignmentTarget.kind === 'card') {
                    await worktreeService.integrateCardWorktree(assignmentTarget.path, deleteBranchAfterCommit)
                }
                else await worktreeService.integrateProjectWorktree()
            }
            if (commitAction === 'update') {
                if (assignmentTarget.kind === 'card') await worktreeService.updateCardWorktree(assignmentTarget.path)
                else await worktreeService.updateProjectWorktree()
            }
        } catch (error) {
            const fallbackMessage = commitAction === 'integrate'
                ? 'Changes were committed, but the worktree could not be integrated into the project'
                : `Changes were committed, but the worktree could not be updated from ${baseName}`
            dialogService.error(error, { fallbackMessage })
        }
    }
    const handleUnassignClose = () => setUnassignDialogOpen(false)
    const handleDropAndUnassign = async () => {
        if (assignmentTarget.kind !== 'card') return

        try {
            await worktreeService.discardAndUnassignCardWorktree(assignmentTarget.path)
            setUnassignDialogOpen(false)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not drop worktree changes' })
        }
    }
    const handleCommitIntegrateAndUnassign = async (message: string) => {
        if (assignmentTarget.kind !== 'card') return

        try {
            await worktreeService.commitCardWorktree(assignmentTarget.path, message)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not commit worktree changes' })
            return
        }

        try {
            await worktreeService.integrateCardWorktree(assignmentTarget.path, false)
        } catch (error) {
            setUnassignDialogOpen(false)
            dialogService.error(error, { fallbackMessage: 'Changes were committed, but the worktree could not be integrated into the project' })
            return
        }

        try {
            await worktreeService.setCardWorktree(assignmentTarget.path, null)
            setUnassignDialogOpen(false)
        } catch (error) {
            setUnassignDialogOpen(false)
            dialogService.error(error, { fallbackMessage: 'Changes were integrated, but the worktree could not be unassigned' })
        }
    }
    const handleIntegrationClose = () => setIntegrationDialogOpen(false)
    const handleDeleteBranchChange = (deleteBranch: boolean) => {
        configService.setReactPreference('react.deleteBranchAfterIntegration', deleteBranch)
    }
    const handleIntegration = async () => {
        if (assignmentTarget.kind !== 'card') return

        if (assignedRecord?.status.dirty) {
            setDeleteBranchAfterCommit(deleteBranchPreference)
            setCommitMessage(getCommitMessage())
            setCommitAction('integrate')
            setIntegrationDialogOpen(false)
            setCommitDialogOpen(true)
            return
        }

        try {
            await worktreeService.integrateCardWorktree(assignmentTarget.path, deleteBranchPreference)
            setIntegrationDialogOpen(false)
        } catch (error) {
            setIntegrationDialogOpen(false)
            dialogService.error(error, { fallbackMessage: 'Could not integrate worktree into project' })
        }
    }

    const button = (
        <IconButton
            aria-label={label}
            disabled={selectorDisabled}
            onClick={handleOpen}
            size="small"
            sx={{
                border: 1,
                borderColor: state.error ? 'error.main' : hasWorktreeChanges ? 'warning.main' : 'divider',
                color: state.error ? 'error.main' : hasWorktreeChanges ? 'warning.main' : 'text.secondary',
                height: 26,
                p: 0,
                pointerEvents: 'auto',
                position: 'relative',
                width: 26,
            }}
        >
            <Box
                sx={{
                    alignItems: 'center',
                    display: 'flex',
                    height: '100%',
                    justifyContent: 'center',
                    // leave room on the right for the arrow gutter so the glyph stays optically centred
                    pr: hasWorktreeChanges ? '8px' : 0,
                    width: '100%',
                }}
            >
                {state.value === 'P' ? <SourceBranch sx={{ fontSize: 14 }} /> : (
                    <Typography component="span" sx={{ fontSize: 11, fontWeight: 700, lineHeight: 1 }}>
                        {state.value}
                    </Typography>
                )}
            </Box>
            {hasWorktreeChanges ? (
                <Box
                    sx={{
                        alignItems: 'center',
                        bottom: 0,
                        display: 'flex',
                        flexDirection: 'column',
                        justifyContent: 'center',
                        position: 'absolute',
                        right: 1,
                        top: 0,
                        width: 8,
                    }}
                >
                    {hasOutgoingChanges ? <ArrowUp sx={{ display: 'block', fontSize: 9 }} /> : null}
                    {hasIncomingChanges ? <ArrowDown sx={{ display: 'block', fontSize: 9 }} /> : null}
                </Box>
            ) : null}
        </IconButton>
    )

    return (
        <>
            <Tooltip title={tooltip}>{selectorDisabled ? <span>{button}</span> : button}</Tooltip>
            <Menu anchorEl={anchorElement} onClose={handleClose} open={!!anchorElement}>
                <MenuItem onClick={handlePrimary} selected={assignment.worktree === null && !assignment.worktreeError}>
                    Primary{primaryPath ? ` â€” ${primaryPath}` : ''}
                </MenuItem>
                {(hasActiveCardWorktree || hasActiveProjectWorktree) ? (
                    <>
                        <MenuItem disabled={!canCommit} onClick={handleCommitMenu}>Commit</MenuItem>
                        <MenuItem disabled={!hasIncomingChanges} onClick={handleUpdateMenu}>Update worktree</MenuItem>
                        <MenuItem disabled={!hasOutgoingChanges} onClick={handleIntegrateMenu}>Integrate into project</MenuItem>
                    </>
                ) : worktrees.map((record, index) => (record.valid ? (
                    <MenuItem
                        data-worktree={index + 1}
                        disabled={assignmentTarget.kind === 'card'
                            && !worktreeService.isWorktreeAvailableForCard(index + 1, assignmentTarget.path)}
                        key={`${index}-${record.path}`}
                        onClick={handleWorktree}
                        selected={assignment.worktree === index + 1}
                    >
                        {index + 1} â€” {record.path}
                    </MenuItem>
                ) : null))}
                {state.error ? <MenuItem disabled selected>{state.value} â€” {state.error}</MenuItem> : null}
            </Menu>
            <WorktreeCommitDialog
                action={commitAction}
                busy={preparing}
                message={commitMessage}
                onClose={handleCommitDialogClose}
                onCommit={handleCommit}
                onMessageChange={setCommitMessage}
                open={commitDialogOpen}
            />
            <WorktreeIntegrationDialog
                busy={preparing}
                deleteBranch={deleteBranchPreference}
                onClose={handleIntegrationClose}
                onDeleteBranchChange={handleDeleteBranchChange}
                onIntegrate={handleIntegration}
                open={integrationDialogOpen}
            />
            <WorktreeUnassignDialog
                busy={preparing}
                commitMessage={commitMessage}
                onClose={handleUnassignClose}
                onCommitMessageChange={setCommitMessage}
                onCommitIntegrate={handleCommitIntegrateAndUnassign}
                onDrop={handleDropAndUnassign}
                open={unassignDialogOpen}
            />
        </>
    )
}

import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type { WorktreeRecord } from '../data/data_types'
import { dialogService } from '../services/dialog_service'
import { configService } from '../services/config/config_service'
import { projectPersistenceService } from '../services/project/project_persistence_service'
import { worktreeService } from '../services/project/worktree_service'
import { AppThemeProvider } from '../theme/theme_provider'
import { WorktreeSelector } from './worktree_selector'

const worktrees: WorktreeRecord[] = [
    {
        branch: 'feature', error: null, parkingBranch: 'md2/parking/feature', path: 'C:\\feature',
        status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: false, hasUpstream: false }, valid: true,
    },
    {
        branch: null, error: 'Folder missing', parkingBranch: 'md2/parking/missing', path: 'C:\\missing',
        status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: false, hasUpstream: false }, valid: false,
    },
]

/** The selector reads the worktree list from the service, so tests seed it there. */
function withRecords(records: WorktreeRecord[]) {
    vi.spyOn(worktreeService, 'getRecords').mockReturnValue(records)
}

function renderAssignedWorktree(record: WorktreeRecord) {
    withRecords([record])
    render(
        <AppThemeProvider>
            <WorktreeSelector
                assignment={{ worktree: 1 }}
                assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                primaryPath="C:\\primary"
            />
        </AppThemeProvider>,
    )
}

describe('WorktreeSelector', () => {
    beforeEach(() => configService.init())

    afterEach(() => {
        cleanup()
        configService.clear()
        window.localStorage.clear()
        vi.restoreAllMocks()
    })

    it('lists Primary and valid linked worktrees while retaining the current invalid assignment', () => {
        withRecords(worktrees)
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 2, worktreeError: null, worktreeValue: '2' }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath={'C:\\primary'}
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: /C:\\missing: Folder missing/u }))

        expect(screen.getByRole('menuitem', { name: /Primary â€” C:\\primary/u })).toBeInTheDocument()
        expect(screen.getByRole('menuitem', { name: /1 â€” C:\\feature/u })).toBeInTheDocument()
        expect(screen.queryByRole('menuitem', { name: /^2 â€” C:\\missing$/u })).not.toBeInTheDocument()
        expect(screen.getByRole('menuitem', { name: /2 â€” C:\\missing: Folder missing/u })).toBeInTheDocument()
    })

    it('cannot open while a run is active', () => {
        withRecords(worktrees)
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: null }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    disabled
                    primaryPath={null}
                />
            </AppThemeProvider>,
        )

        const button = screen.getByRole('button', { name: 'Primary worktree' })
        expect(button).toBeDisabled()
        fireEvent.click(button)
        expect(screen.queryByRole('menu')).not.toBeInTheDocument()
    })

    it('disables a worktree reserved by another active card', () => {
        withRecords(worktrees)
        vi.spyOn(worktreeService, 'isWorktreeAvailableForCard').mockReturnValue(false)
        const setCardWorktree = vi.spyOn(worktreeService, 'setCardWorktree')
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: null }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath={null}
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: 'Primary worktree' }))
        const reservedWorktree = screen.getByRole('menuitem', { name: '1 â€” C:\\feature' })
        expect(reservedWorktree).toHaveAttribute('aria-disabled', 'true')
        fireEvent.click(reservedWorktree)
        expect(setCardWorktree).not.toHaveBeenCalled()
    })

    it('shows lifecycle actions instead of worktree choices for an assigned card', () => {
        withRecords(worktrees)
        const refresh = vi.spyOn(worktreeService, 'refresh').mockResolvedValue(undefined)
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 1 }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath="C:\\primary"
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))

        expect(refresh).not.toHaveBeenCalled()

        expect(screen.getByRole('menuitem', { name: /Primary â€” C:.*primary/u })).toBeInTheDocument()
        expect(screen.getByRole('menuitem', { name: 'Commit' })).toHaveAttribute('aria-disabled', 'true')
        expect(screen.getByRole('menuitem', { name: 'Update worktree' })).toHaveAttribute('aria-disabled', 'true')
        expect(screen.getByRole('menuitem', { name: 'Integrate into project' })).toHaveAttribute('aria-disabled', 'true')
        expect(screen.queryByRole('menuitem', { name: /1 â€” C:\\feature/u })).not.toBeInTheDocument()
    })

    it('ignores upstream state when deciding project-worktree actions', () => {
        const synchronizedWorktree = {
            ...worktrees[0],
            status: { ...worktrees[0].status, hasUpstream: true },
        }
        renderAssignedWorktree(synchronizedWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))

        expect(screen.getByRole('menuitem', { name: 'Commit' })).toHaveAttribute('aria-disabled', 'true')
        expect(screen.getByRole('menuitem', { name: 'Update worktree' })).toHaveAttribute('aria-disabled', 'true')
        expect(screen.getByRole('menuitem', { name: 'Integrate into project' })).toHaveAttribute('aria-disabled', 'true')
    })

    it('integrates a clean worktree when it is ahead of the project branch', async () => {
        const aheadWorktree = {
            ...worktrees[0],
            status: { ...worktrees[0].status, ahead: 1, baseAhead: 1, hasUpstream: true },
        }
        const integrateCardWorktree = vi.spyOn(worktreeService, 'integrateCardWorktree').mockResolvedValue(undefined)
        renderAssignedWorktree(aheadWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Integrate into project' }))
        expect(screen.getByRole('checkbox', { name: 'Delete branch' })).not.toBeChecked()
        fireEvent.click(screen.getByRole('button', { name: 'Integrate' }))

        await vi.waitFor(() => expect(integrateCardWorktree).toHaveBeenCalledWith('design/F-1.md', false))
    })

    it('updates a clean worktree when it is behind the project branch', async () => {
        const behindWorktree = {
            ...worktrees[0],
            status: { ...worktrees[0].status, baseBehind: 1 },
        }
        const updateCardWorktree = vi.spyOn(worktreeService, 'updateCardWorktree').mockResolvedValue(undefined)
        renderAssignedWorktree(behindWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Update worktree' }))

        await vi.waitFor(() => expect(updateCardWorktree).toHaveBeenCalledWith('design/F-1.md'))
    })

    it('uses pending project saves for both incoming indicator and update availability', () => {
        vi.spyOn(projectPersistenceService, 'getSnapshot').mockReturnValue({hasPendingPush: false, hasPendingSave: true, localSaveState: 'dirty'})
        renderAssignedWorktree(worktrees[0])

        const button = screen.getByRole('button', { name: /project changes pending yes/u })
        fireEvent.click(button)

        expect(screen.getByRole('menuitem', { name: 'Update worktree' })).not.toHaveAttribute('aria-disabled')
    })

    it('uses uncommitted primary files for both incoming indicator and update availability', () => {
        vi.spyOn(worktreeService, 'getPrimaryStatus').mockReturnValue({ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: true, hasUpstream: true})
        renderAssignedWorktree(worktrees[0])

        const button = screen.getByRole('button', { name: /project changes pending yes/u })
        fireEvent.click(button)

        expect(screen.getByRole('menuitem', { name: 'Update worktree' })).not.toHaveAttribute('aria-disabled')
    })

    it('asks how to resolve dirty changes before returning to Primary', async () => {
        const dirtyWorktrees = [{
            ...worktrees[0],
            status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: true, hasUpstream: false },
        }]
        withRecords(dirtyWorktrees)
        vi.spyOn(worktreeService, 'getCardCommitMessage').mockReturnValue('F-1: Card')
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 1 }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath="C:\\primary"
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: /Primary/u }))

        expect(await screen.findByRole('dialog', { name: 'Worktree has uncommitted changes' })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'Drop changes' })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'Commit & integrate' })).toBeInTheDocument()
    })

    it('commits, integrates, and unassigns dirty worktree changes in order', async () => {
        const dirtyWorktree = { ...worktrees[0], status: { ...worktrees[0].status, dirty: true } }
        vi.spyOn(worktreeService, 'getCardCommitMessage').mockReturnValue('F-1: Card')
        const commitCardWorktree = vi.spyOn(worktreeService, 'commitCardWorktree').mockResolvedValue(undefined)
        const integrateCardWorktree = vi.spyOn(worktreeService, 'integrateCardWorktree').mockResolvedValue(undefined)
        const setCardWorktree = vi.spyOn(worktreeService, 'setCardWorktree').mockResolvedValue(undefined)
        renderAssignedWorktree(dirtyWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: /Primary/u }))
        fireEvent.click(await screen.findByRole('button', { name: 'Commit & integrate' }))

        await vi.waitFor(() => expect(setCardWorktree).toHaveBeenCalledWith('design/F-1.md', null))
        expect(commitCardWorktree.mock.invocationCallOrder[0]).toBeLessThan(integrateCardWorktree.mock.invocationCallOrder[0])
        expect(integrateCardWorktree).toHaveBeenCalledWith('design/F-1.md', false)
        expect(integrateCardWorktree.mock.invocationCallOrder[0]).toBeLessThan(setCardWorktree.mock.invocationCallOrder[0])
    })

    it('opens the dirty dialog when backend revalidation rejects parking', async () => {
        const dirtyWorktree = { ...worktrees[0], status: { ...worktrees[0].status, dirty: true } }
        vi.spyOn(worktreeService, 'setCardWorktree').mockRejectedValue(new Error('Linked worktree has uncommitted changes'))
        withRecords([dirtyWorktree])
        vi.spyOn(worktreeService, 'getCardCommitMessage').mockReturnValue('F-1: Card')
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 1 }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath="C:\\primary"
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: /Primary/u }))

        expect(await screen.findByRole('dialog', { name: 'Worktree has uncommitted changes' })).toBeInTheDocument()
    })

    it('offers an update for a worktree trailing the project branch without an upstream', async () => {
        const trailingWorktrees = [{
            ...worktrees[0],
            status: { ahead: 0, baseAhead: 0, baseBehind: 2, behind: 0, dirty: false, hasUpstream: false },
        }]
        withRecords(trailingWorktrees)
        vi.spyOn(worktreeService, 'getProjectBranch').mockReturnValue('main')
        const updateCardWorktree = vi.spyOn(worktreeService, 'updateCardWorktree').mockResolvedValue(undefined)
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 1 }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath="C:\\primary"
                />
            </AppThemeProvider>,
        )

        const button = screen.getByRole('button', { name: /Worktree 1/u })
        expect(button).toHaveAccessibleName(/behind main 2/u)
        expect(button).toHaveStyle({ color: 'rgb(249, 168, 37)' })

        fireEvent.click(button)
        fireEvent.click(screen.getByRole('menuitem', { name: 'Update worktree' }))

        await vi.waitFor(() => expect(updateCardWorktree).toHaveBeenCalledWith('design/F-1.md'))
    })

    it('disables update when the worktree is already up to date with the project branch', () => {
        withRecords([worktrees[0]])
        vi.spyOn(worktreeService, 'getProjectBranch').mockReturnValue('main')
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 1 }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath="C:\\primary"
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))

        expect(screen.getByRole('menuitem', { name: 'Update worktree' })).toHaveAttribute('aria-disabled', 'true')
    })

    it('opens the commit dialog with the default card message', () => {
        const dirtyWorktrees = [{
            ...worktrees[0],
            status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: true, hasUpstream: false },
        }]
        withRecords(dirtyWorktrees)
        vi.spyOn(worktreeService, 'getCardCommitMessage').mockReturnValue('F-1: Card')
        const commitCardWorktree = vi.spyOn(worktreeService, 'commitCardWorktree').mockResolvedValue(undefined)
        render(
            <AppThemeProvider>
                <WorktreeSelector
                    assignment={{ worktree: 1 }}
                    assignmentTarget={{ kind: 'card', path: 'design/F-1.md' }}
                    primaryPath="C:\\primary"
                />
            </AppThemeProvider>,
        )

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Commit' }))
        expect(screen.getByRole('dialog', { name: 'Commit worktree' })).toBeInTheDocument()
        expect(screen.getByRole('textbox')).toHaveValue('F-1: Card')

        fireEvent.click(screen.getByRole('button', { name: 'Commit' }))
        expect(commitCardWorktree).toHaveBeenCalledWith('design/F-1.md', 'F-1: Card')
    })

    it('reports commit errors through dialogService and leaves the commit dialog open', async () => {
        const dirtyWorktree = { ...worktrees[0], status: { ...worktrees[0].status, dirty: true } }
        const error = new Error('commit failed')
        vi.spyOn(worktreeService, 'getCardCommitMessage').mockReturnValue('F-1: Card')
        vi.spyOn(worktreeService, 'commitCardWorktree').mockRejectedValue(error)
        const reportError = vi.spyOn(dialogService, 'error')
        renderAssignedWorktree(dirtyWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Commit' }))
        fireEvent.click(screen.getByRole('button', { name: 'Commit' }))

        await vi.waitFor(() => expect(reportError).toHaveBeenCalledWith(error, {fallbackMessage: 'Could not commit worktree changes'}))
        expect(screen.getByRole('dialog', { name: 'Commit worktree' })).toBeInTheDocument()
    })

    it('closes the commit dialog and reports an integration error after the commit succeeds', async () => {
        const dirtyWorktree = { ...worktrees[0], status: { ...worktrees[0].status, dirty: true } }
        const error = new Error('integration failed')
        vi.spyOn(worktreeService, 'getCardCommitMessage').mockReturnValue('F-1: Card')
        const commitCardWorktree = vi.spyOn(worktreeService, 'commitCardWorktree').mockResolvedValue(undefined)
        vi.spyOn(worktreeService, 'integrateCardWorktree').mockRejectedValue(error)
        const reportError = vi.spyOn(dialogService, 'error')
        renderAssignedWorktree(dirtyWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Integrate into project' }))
        fireEvent.click(screen.getByRole('button', { name: 'Integrate' }))
        fireEvent.click(screen.getByRole('button', { name: 'Commit & integrate' }))

        await vi.waitFor(() => expect(reportError).toHaveBeenCalledWith(error, {fallbackMessage: 'Changes were committed, but the worktree could not be integrated into the project'}))
        expect(commitCardWorktree).toHaveBeenCalledWith('design/F-1.md', 'F-1: Card')
        await vi.waitFor(() => {
            expect(screen.queryByRole('dialog', { name: 'Commit and integrate worktree' })).not.toBeInTheDocument()
        })
    })

    it('reports update errors through dialogService', async () => {
        const behindWorktree = {
            ...worktrees[0],
            status: { ...worktrees[0].status, baseBehind: 1 },
        }
        const error = new Error('update failed')
        vi.spyOn(worktreeService, 'updateCardWorktree').mockRejectedValue(error)
        const reportError = vi.spyOn(dialogService, 'error')
        renderAssignedWorktree(behindWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Update worktree' }))

        await vi.waitFor(() => expect(reportError).toHaveBeenCalledWith(error, {fallbackMessage: 'Could not update worktree from the project branch'}))
    })

    it('reports integration errors through dialogService', async () => {
        const trailingWorktree = {
            ...worktrees[0],
            status: { ...worktrees[0].status, baseAhead: 1 },
        }
        const error = new Error('integration failed')
        vi.spyOn(worktreeService, 'getProjectBranch').mockReturnValue('main')
        vi.spyOn(worktreeService, 'integrateCardWorktree').mockRejectedValue(error)
        const reportError = vi.spyOn(dialogService, 'error')
        renderAssignedWorktree(trailingWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Integrate into project' }))
        fireEvent.click(screen.getByRole('button', { name: 'Integrate' }))

        await vi.waitFor(() => expect(reportError).toHaveBeenCalledWith(error, {fallbackMessage: 'Could not integrate worktree into project'}))
    })

    it('restores and applies the persisted delete-branch integration choice', async () => {
        configService.setReactPreference('react.deleteBranchAfterIntegration', true)
        const aheadWorktree = { ...worktrees[0], status: { ...worktrees[0].status, baseAhead: 1 } }
        const integrateCardWorktree = vi.spyOn(worktreeService, 'integrateCardWorktree').mockResolvedValue(undefined)
        renderAssignedWorktree(aheadWorktree)

        fireEvent.click(screen.getByRole('button', { name: /Worktree 1/u }))
        fireEvent.click(screen.getByRole('menuitem', { name: 'Integrate into project' }))

        expect(screen.getByRole('checkbox', { name: 'Delete branch' })).toBeChecked()
        fireEvent.click(screen.getByRole('button', { name: 'Integrate' }))
        await vi.waitFor(() => expect(integrateCardWorktree).toHaveBeenCalledWith('design/F-1.md', true))
    })
})

